param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'type-find-interfaces-reentrancy-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
function Value($value,$self){if($null -eq $value){return $null};if($value -is [Type]){if([object]::ReferenceEquals($value,$self)){return 'self'};return 'type:'+$value.ToString()};if($value -is [bool]){return $value.ToString().ToLowerInvariant()};if($value -is [Enum]){return ([int]$value).ToString()};if($value -is [Array]){return (($value|ForEach-Object {Value $_ $self})-join ';')};return $value.ToString()}
function Resolve($name){if($name -eq 'GenericListP'){return [object].Assembly.GetType('System.Collections.Generic.List`1').GetGenericArguments()[0]};if($name -eq 'GenericDictP'){return [object].Assembly.GetType('System.Collections.Generic.Dictionary`2').GetGenericArguments()[0]};if($name -eq 'GenericDictQ'){return [object].Assembly.GetType('System.Collections.Generic.Dictionary`2').GetGenericArguments()[1]};if($name -eq 'SigListArray'){return (Resolve 'SigList').MakeArrayType()};if($name -eq 'SigListRef'){return (Resolve 'SigList').MakeByRefType()};if($name -eq 'SigEmpty'){return [Type]::MakeGenericSignatureType([object].Assembly.GetType('System.Collections.Generic.List`1'),[Type[]]::new(0))};if($name.Contains('@')){$parts=$name.Split('@');$value=Resolve $parts[0];switch($parts[1]){'sz'{return $value.MakeArrayType()};'rank'{return $value.MakeArrayType(2)};'ptr'{return $value.MakePointerType()};'ref'{return $value.MakeByRefType()}}};if($name -eq 'NullableInt'){return [object].Assembly.GetType('System.Nullable`1').MakeGenericType([Type[]]@([int]))};$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$dict=[object].Assembly.GetType('System.Collections.Generic.Dictionary`2');$nullable=[object].Assembly.GetType('System.Nullable`1');switch($name){'null'{return $null};'ListD'{return $list};'DictD'{return $dict};'NullableD'{return $nullable};'TupleD'{return [object].Assembly.GetType('System.ValueTuple`2')};'ListS'{return $list.MakeGenericType([type[]]@([string]))};'Sig0'{return [Type]::MakeGenericMethodParameter(0)};'Sig1'{return [Type]::MakeGenericMethodParameter(1)};'Sig0Array'{return [Type]::MakeGenericMethodParameter(0).MakeArrayType()};'Sig0Ref'{return [Type]::MakeGenericMethodParameter(0).MakeByRefType()};'SigList'{return [Type]::MakeGenericSignatureType($list,[type[]]@([Type]::MakeGenericMethodParameter(0)))};default{return [Type]::GetType('System.'+$name,$true,$false)}}}
function Names($types){return (($types|ForEach-Object {$_.FullName})-join ';')}
function SelectInterfaces($type,$mode,$criteria,$state,$reenter){$local=@{index=0};$filter=[Reflection.TypeFilter]({param([Type]$t,[object]$c)$index=$local.index;$local.index++;$nested='';if($reenter -and $index -eq 0){$state.calls++;$nested=Names ($type.FindInterfaces([Reflection.TypeFilter]{param($x,$y)return $true},$criteria))};$state.trace.Add($t.FullName+'#'+[object]::ReferenceEquals($c,$criteria).ToString().ToLowerInvariant()+'#'+$nested);switch($mode){'All'{return $true};'None'{return $false};'Alternating'{return ($index % 2) -eq 0};default{throw 'unknown mode'}}}.GetNewClosure());$state.calls++;$result=$type.FindInterfaces($filter,$criteria);return ,$result}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$total=0
foreach($case in $plan.cases){$type=Resolve $case.type;$criteria=[object]::new();$state=@{trace=[Collections.Generic.List[string]]::new();calls=0};$value=$null;$errorName='none';$message=$null;$hResult=0;$param=$null;try{$first=SelectInterfaces $type $case.mode $criteria $state ($case.experiment -eq 'Reenter');$names=Names $first;$state.trace.Add('//');$second=SelectInterfaces $type $case.mode $criteria $state ($case.experiment -eq 'Reenter');$same=[object]::ReferenceEquals($first,$second).ToString().ToLowerInvariant();$after='';if($case.experiment -eq 'Mutate'){if($first.Length -gt 0){$first[0]=$null};$state.trace.Add('//');$third=SelectInterfaces $type $case.mode $criteria $state $false;$after=Names $third};$value=$same+'|'+$names+'|'+(Names $second)+'|'+$after+'|'+($state.trace -join ';')}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{id=$case.id;valueUnits=(Units $value);exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param);calls=$state.calls});$total+=$state.calls}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();nativeCalls=$total;qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS FindInterfaces repeat capture: $($rows.Count) cases, $total facade calls"
